def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    dirs = [(0, 1), (1, 0), (1, 1), (1, -1)]

    def is_blocked(r, c):
        return not (0 <= r < h and 0 <= c < w) or grid[r][c] != bg

    def side_blocked(r, c, dr, dc):
        for ar in (-1, 0, 1):
            for ac in (-1, 0, 1):
                if ar == 0 and ac == 0:
                    continue
                if (ar, ac) == (dr, dc) or (ar, ac) == (-dr, -dc):
                    continue
                rr, cc = r + ar, c + ac
                if 0 <= rr < h and 0 <= cc < w and grid[rr][cc] != bg:
                    return True
        return False

    for dr, dc in dirs:
        for r in range(h):
            for c in range(w):
                color = grid[r][c]
                if color == bg:
                    continue
                pr, pc = r - dr, c - dc
                if 0 <= pr < h and 0 <= pc < w and grid[pr][pc] == color:
                    continue

                cells = []
                rr, cc = r, c
                while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == color:
                    cells.append((rr, cc))
                    rr += dr
                    cc += dc
                if len(cells) < 2:
                    continue

                r0, c0 = cells[0]
                r1, c1 = cells[-1]
                before = is_blocked(r0 - dr, c0 - dc) or side_blocked(r0, c0, dr, dc)
                after = is_blocked(r1 + dr, c1 + dc) or side_blocked(r1, c1, dr, dc)

                if before and not after:
                    rr, cc = r1 + dr, c1 + dc
                    while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == bg:
                        out[rr][cc] = color
                        rr += dr
                        cc += dc
                elif after and not before:
                    rr, cc = r0 - dr, c0 - dc
                    while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == bg:
                        out[rr][cc] = color
                        rr -= dr
                        cc -= dc

    return out
